import { RandomImpl } from "#base/scripts/random-pcg-32.js";
import {
	ContinentGenerator,
	continentGeneratorRulesSettings,
	continentGeneratorSchema,
	ContinentGeneratorSettings,
} from "#base/scripts/voronoi_generators/continent-generator.js";

import pangaeaSettings from "../voronoi_data/pangaea.mapconfig.js";
import { VoronoiMap, voronoiMapSchema } from "../voronoi_maps/map-common.js";

export class VoronoiPangaea extends VoronoiMap {
	constructor() {
		const generator = new ContinentGenerator(
			{ ...continentGeneratorSchema },
			{ ...continentGeneratorRulesSettings },
		);
		super(
			{ ...voronoiMapSchema },
			generator,
			generator.getDefaultGeneratorSettings(),
			generator.getDefaultRuleSettings(),
			pangaeaSettings,
		);
	}

	static getName(): string {
		return "Pangaea";
	}

	override init(hexDims: float2) {
		this.initInternal(hexDims);
	}

	override simulateInternal(): void {
		const settings = this.getGenerator().getSettings() as ContinentGeneratorSettings;
		settings.landmass[0].playerAreas = this.getSettings().totalPlayers;
		settings.landmass[0].xPos = 0.4 + RandomImpl.fRand("Pangaea seed x") * 0.2;
		settings.landmass[0].yPos = 0.4 + RandomImpl.fRand("Pangaea seed y") * 0.2;
	}

	override getFilename(): string {
		return "pangaea.mapconfig.js";
	}
}
